bool isTrackVisible(String path) {
  final rowContext = rowKeys[path]?.currentContext;
  if (rowContext == null) return false;

  // During rebuilds (e.g. while the selector is evaluating), Flutter may
  // temporarily mark a context as inactive; findRenderObject() then throws.
  try {
    final row = rowContext.findRenderObject();
    // If the row has a live RenderBox, it means it has been built by the
    // scrollable and is part of the current visible set.
    return row is RenderBox;
  } catch (_) {
    return false;
  }
}
